<script>
(function($){
function toast(msg){$('.toast-body').text(msg);bootstrap.Toast.getOrCreateInstance(document.getElementById('siteToast')).show()}
$('#availabilityForm').on('submit',function(e){e.preventDefault();$('html,body').animate({scrollTop:$('#rooms').offset().top-90},500);toast('Showing our available room options.')});
$('[data-room]').on('click',function(){var room=$(this).data('room');$('#bookingModal select[name=room]').val(room);bootstrap.Modal.getOrCreateInstance('#bookingModal').show()});
$('#bookingForm').on('submit',function(e){e.preventDefault();bootstrap.Modal.getOrCreateInstance('#bookingModal').hide();toast('Reservation request received. Reception can now confirm your stay.')});
$('#transportForm').on('submit',function(e){e.preventDefault();bootstrap.Modal.getOrCreateInstance('#transportModal').hide();toast('Transfer request received. Hotel transport can confirm pickup details.')});
$('#createForm').on('submit',function(e){e.preventDefault();var data=$(this).serializeArray(),payload={};$.each(data,function(_,x){payload[x.name]=x.value});$.ajax({url:'api.php?action=create',method:'POST',contentType:'application/json',data:JSON.stringify(payload)}).done(function(){bootstrap.Modal.getOrCreateInstance('#createModal').hide();toast('Trip published successfully.');loadTrips()}).fail(function(){bootstrap.Modal.getOrCreateInstance('#createModal').hide();toast('The trip form is ready; database setup is required for permanent publishing.')})});
function loadTrips(){$.getJSON('api.php?action=list').done(function(r){var trips=r.trips||[];if(!trips.length){$('#tripList').html('<div class="col-12"><div class="alert alert-light border">No trips are published yet. Use Create a trip to add the first one.</div></div>');return}var html='';$.each(trips,function(_,t){html+='<div class="col-md-6 col-lg-4"><article class="trip-card"><img src="'+(t.image_url||'https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=900&q=80')+'" alt=""><div class="trip-body"><span class="badge badge-live rounded-pill px-3 py-2">'+(t.destination||'Tanzania')+'</span><h3 class="mt-3">'+(t.title||'Tanzania experience')+'</h3><p class="text-muted small">'+(t.description||'A planned Tanzania travel experience.')+'</p><div class="d-flex justify-content-between small text-muted mb-3"><span><i class="bi bi-calendar3"></i> '+(t.trip_date||'Date TBA')+'</span><span><i class="bi bi-people"></i> '+(t.capacity||0)+' guests</span></div><button class="btn btn-gold w-100 join-trip" data-id="'+(t.id||'')+'">Join trip</button></div></article></div>'});$('#tripList').html(html)}).fail(function(){$('#tripList').html('<div class="col-12"><div class="alert alert-light border">Travel desk is ready. Connect the database in setup.php to enable live trip management.</div></div>')})}
$(document).on('click','.join-trip',function(){var id=$(this).data('id');var name=prompt('Your name');if(!name)return;var phone=prompt('Your phone / WhatsApp');if(!phone)return;$.ajax({url:'api.php?action=join',method:'POST',contentType:'application/json',data:JSON.stringify({trip_id:id,name:name,phone:phone})}).done(function(){toast('Your trip request has been sent.')}).fail(function(){toast('Trip joining requires the database to be configured.')})});
$('#travelSwitch').on('click',function(){$('html,body').animate({scrollTop:$('#tours').offset().top-80},650)});
loadTrips();
})(jQuery);
</script>
</body></html>